module Counter : sig
  type t

  val create : int -> t
  val incr : t -> t option
  val value : t -> int
end = struct
  (* AF: {limit; v} is a counter that has counted v of at most limit steps.
     RI: limit > 0 && 0 <= v && v <= limit. *)
  type t = { limit : int; v : int }

  let rep_ok c =
    assert (c.limit > 0 && c.v >= 0 && c.v <= c.limit);
    c

  let create limit =
    if limit <= 0 then invalid_arg "Counter.create: limit must be positive"
    else rep_ok { limit; v = 0 }

  let incr c = if c.v = c.limit then None else Some (rep_ok { c with v = c.v + 1 })
  let value c = c.v
end

(** [sqrt_floor n] requires [n >= 0] and returns the greatest [r] with [r * r <= n].
    Raises [Invalid_argument] if [n < 0]. *)
let sqrt_floor n =
  if n < 0 then invalid_arg "sqrt_floor: negative";
  let r = ref 0 in
  while (!r + 1) * (!r + 1) <= n do incr r done;
  !r

