let classify a b c =
  if a <= 0 || b <= 0 || c <= 0 then "invalid"
  else if a + b <= c || a + c <= b || b + c <= a then "invalid"
  else if a = b && b = c then "equilateral"
  else if a = b || b = c || a = c then "isosceles"
  else "scalene"

(* The same logic with the branch number returned, for glass-box coverage. *)
let traced a b c =
  if a <= 0 || b <= 0 || c <= 0 then (1, "invalid")
  else if a + b <= c || a + c <= b || b + c <= a then (2, "invalid")
  else if a = b && b = c then (3, "equilateral")
  else if a = b || b = c || a = c then (4, "isosceles")
  else (5, "scalene")

