    ((3, 2, 3), "isosceles"); ((3, 4, 5), "scalene"); ((1, 2, 3), "invalid");
    ((0, 1, 1), "invalid"); ((-1, 2, 2), "invalid"); ((1, 1, 3), "invalid") ]

let covered tests =
  List.sort_uniq compare (List.map (fun ((a, b, c), _) -> fst (traced a b c)) tests)

