  Printf.printf "with only three tests: %d of 5\n" (List.length (covered first_three));
  let agree = List.for_all (fun ((a, b, c), _) -> snd (traced a b c) = classify a b c) tests in
  Printf.printf "traced version agrees: %b\n" agree

