let rec all n = if n = 0 then [ [] ] else List.concat_map (fun l -> List.map (fun x -> x :: l) [ 0; 1; 2 ]) (all (n - 1))
let universe = List.concat_map all [ 0; 1; 2; 3; 4 ]
let small = List.concat_map all [ 0; 1; 2; 3 ]

let rec rev = function [] -> [] | x :: xs -> rev xs @ [ x ]
let rev_tr l = let rec go acc = function [] -> acc | x :: xs -> go (x :: acc) xs in go [] l
let rec sum = function [] -> 0 | x :: xs -> x + sum xs
let sum_tr l = let rec go acc = function [] -> acc | x :: xs -> go (acc + x) xs in go 0 l

let pairs p = List.for_all (fun a -> List.for_all (fun b -> p a b) universe) universe

let () =
  let n = List.length universe in
  Printf.printf "%d lists, %d pairs\n" n (n * n);
  Printf.printf "rev (a @ b) = rev b @ rev a: %b\n" (pairs (fun a b -> rev (a @ b) = rev b @ rev a));
  Printf.printf "length (a @ b) = length a + length b: %b\n"
    (pairs (fun a b -> List.length (a @ b) = List.length a + List.length b));
  let triples =
    List.for_all (fun a -> List.for_all (fun b -> List.for_all (fun c -> (a @ b) @ c = a @ (b @ c)) small) small) small
  in
  Printf.printf "append is associative on %d triples: %b\n" (List.length small * List.length small * List.length small) triples;
  Printf.printf "rev_tr agrees with rev: %b\n" (List.for_all (fun l -> rev_tr l = rev l) universe);
  Printf.printf "sum_tr agrees with sum: %b\n" (List.for_all (fun l -> sum_tr l = sum l) universe);
  Printf.printf "a false claim, rev (a @ b) = rev a @ rev b: %b\n" (pairs (fun a b -> rev (a @ b) = rev a @ rev b))

